def find_divisors(n):
    divs = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def solve_task():
    successful_extensions = []

    # Search up to x2 = 100 as requested
    MAX_X2 = 100

    print("Starting systematic search for n=4 extensions...")

    for x2 in range(1, MAX_X2 + 1):
        K = x2**2 + 1
        divs = find_divisors(K)

        # Iterate through possible values for x1 + 1 (let d = x1 + 1)
        for d in divs:
            # x1 and x3 must be positive integers, so d >= 2 and K/d >= 2
            if d < 2 or K // d < 2:
                continue

            x1 = d - 1
            x3 = (K // d) - 1

            # Check the condition for extension to n=4: (x2+1) | (x3^2 - x2)
            numerator = x3**2 - x2
            denominator = x2 + 1

            if numerator % denominator == 0:
                # We found a successful extension (x1, x2, x3)
                print(f"Found solution for x2={x2}: ({x1}, {x2}, {x3})")
                successful_extensions.append((x1, x2, x3))

    return successful_extensions

solutions = solve_task()
print("\n--- Final Results ---")
if solutions:
    print(f"Total successful extensions found: {len(solutions)}")
    print("List of solutions (x1, x2, x3):")
    for sol in solutions:
        print(sol)
else:
    print("No successful extensions found within the search limit.")

